// Boundary check of the 1 MiB import limit, using the real app/backup.js. Changes nothing in the repo.
const path = require('node:path');
const backup = require(path.resolve(process.argv[2], 'app/backup.js'));
const { MAX_IMPORT_BYTES, MESSAGES, toBackupText, tooBigToImport, importBackup } = backup;

const bytes = (s) => new TextEncoder().encode(s).length;

// A valid backup padded with trailing spaces (JSON.parse ignores them) to exactly `target` UTF-8 bytes.
function backupOf(target, title) {
  const base = toBackupText([{ id: 'a1', title, done: false, createdAt: 1700000000000 }]);
  const text = base + ' '.repeat(target - bytes(base));
  if (bytes(text) !== target) throw new Error('padding wrong');
  return text;
}

function fakeStore() {
  const calls = [];
  return { calls, readError: false, save: () => 'saved', replace: (t) => { calls.push(t); return 'saved'; } };
}

async function run(label, text) {
  const blob = new Blob([text]);
  const store = fakeStore();
  const r = await importBackup({ store, current: [], file: blob, ask: async () => true });
  const verdict = r.message === MESSAGES.fileTooBig ? 'REJECTED fileTooBig' : `accepted -> "${r.message}"`;
  console.log(
    `${label}: chars=${text.length} utf8Bytes=${bytes(text)} blob.size=${blob.size} ` +
    `tooBigToImport=${tooBigToImport(text)} importBackup=${verdict} replaceCalls=${store.calls.length}`,
  );
  return { tooBig: tooBigToImport(text), rejected: r.message === MESSAGES.fileTooBig };
}

(async () => {
  console.log(`MAX_IMPORT_BYTES = ${MAX_IMPORT_BYTES} (1 MiB = ${1024 * 1024})`);
  const results = [];
  for (const [title, kind] of [['Mua sua', 'ascii'], ['Mua sữa ở chợ', 'multibyte']]) {
    results.push(['exact ' + kind, await run(`${kind} N-1   `, backupOf(MAX_IMPORT_BYTES - 1, title)), false]);
    results.push(['exact ' + kind, await run(`${kind} N     `, backupOf(MAX_IMPORT_BYTES, title)), false]);
    results.push(['exact ' + kind, await run(`${kind} N+1   `, backupOf(MAX_IMPORT_BYTES + 1, title)), true]);
  }
  // Multibyte trap: fewer than N chars but more than N bytes must be rejected.
  const t = backupOf(MAX_IMPORT_BYTES + 1, 'ữ'.repeat(1000));
  results.push(['chars<N bytes>N', await run('multibyte chars<N, bytes=N+1', t), true]);

  const bad = results.filter(([, r, expectTooBig]) => r.tooBig !== expectTooBig || r.rejected !== expectTooBig);
  console.log(bad.length === 0 ? 'RESULT: limit is exact (N passes, N+1 rejected, in both checks)' : `RESULT: ${bad.length} MISMATCH(ES)`);
  process.exitCode = bad.length === 0 ? 0 : 1;
})();

